import { Menu as BaseMenu } from "@base-ui/react/menu";
import * as React from "react";
import {
  createContext,
  forwardRef,
  useContext,
  useCallback,
  useImperativeHandle,
  useRef,
} from "react";

import { cn, resolveClassName } from "@/lib/cn";
import { useGlide } from "@/lib/glide";
import { useOverlayRoot, useOverlayDismiss } from "@/components/ui/overlay-root";

/** Details supplied to a DropdownMenu open-change callback. */
export type DropdownMenuChangeDetails = BaseMenu.Root.ChangeEventDetails;
/** Supported DropdownMenuChangeReason values. */
export type DropdownMenuChangeReason = BaseMenu.Root.ChangeEventReason;
/** Supported DropdownMenuInteractionOwner values. */
export type DropdownMenuInteractionOwner = "host" | "local";

type MenuContextValue = {
  actionsRef: React.RefObject<BaseMenu.Root.Actions | null>;
  interactionOwner: DropdownMenuInteractionOwner;
};

const MenuContext = createContext<MenuContextValue | null>(null);
/** Props accepted by DropdownMenu. */
export type DropdownMenuProps<Payload = unknown> =
  BaseMenu.Root.Props<Payload> & {
    interactionOwner?: DropdownMenuInteractionOwner;
  };

/** A menu controller with explicit controlled or uncontrolled open state. */
export function DropdownMenu<Payload = unknown>({
  actionsRef: suppliedActionsRef,
  children,
  interactionOwner = "local",
  onOpenChange,
  ...props
}: DropdownMenuProps<Payload>) {
  const internalActionsRef = useRef<BaseMenu.Root.Actions>(null);
  const actionsRef = suppliedActionsRef ?? internalActionsRef;
  useOverlayDismiss(() => actionsRef.current?.close());
  return (
    <MenuContext.Provider value={{ actionsRef, interactionOwner }}>
      <BaseMenu.Root
        {...props}
        actionsRef={actionsRef}
        onOpenChange={(next, details) => {
          if (
            interactionOwner === "host" &&
            !next &&
            details.reason === "escape-key"
          ) {
            details.cancel();
            details.allowPropagation();
            return;
          }
          onOpenChange?.(next, details);
        }}
      >
        {children}
      </BaseMenu.Root>
    </MenuContext.Provider>
  );
}

/** Access the nearest DropdownMenu close operation. */
export function useDropdownMenu() {
  const menu = useMenu();
  return {
    /** Close the nearest menu, if it is mounted. */
    close: () => menu.actionsRef.current?.close(),
  };
}
function useMenu() {
  const value = useContext(MenuContext);
  if (!value)
    throw new Error("DropdownMenu parts must be used inside <DropdownMenu>");
  return value;
}

/** The trigger control for a DropdownMenu. */
export const DropdownMenuTrigger = forwardRef<
  HTMLButtonElement,
  BaseMenu.Trigger.Props
>(function DropdownMenuTrigger(
  { className, render, type = "button", ...props },
  ref,
) {
  return (
    <BaseMenu.Trigger
      {...props}
      className={(state) =>
        cn("btn caps-dropdown-trigger", resolveClassName(className, state))
      }
      ref={ref}
      render={render}
      type={type}
    />
  );
});

/** Shell popover destination, with Base UI container and mount lifetime overrides. */
export const DropdownMenuPortal = forwardRef<
  HTMLDivElement,
  BaseMenu.Portal.Props
>(function DropdownMenuPortal({ container, ...props }, ref) {
  const root = useOverlayRoot("popover");
  if (container == null && root === null) return null;
  return <BaseMenu.Portal {...props} container={container ?? root} ref={ref} />;
});

/** Base UI owns placement; a shell's popover root supplies its collision boundary. */
export const DropdownMenuPositioner = forwardRef<
  HTMLDivElement,
  BaseMenu.Positioner.Props
>(function DropdownMenuPositioner({ collisionBoundary, ...props }, ref) {
  const root = useOverlayRoot("popover");
  return (
    <BaseMenu.Positioner
      {...props}
      collisionBoundary={
        collisionBoundary ?? (root && root !== document.body ? root : undefined)
      }
      ref={ref}
    />
  );
});

/** The styled popup for caller-composed menu placement and portal ownership. */
export const DropdownMenuPopup = forwardRef<
  HTMLDivElement,
  BaseMenu.Popup.Props
>(function DropdownMenuPopup({ className, finalFocus, ...props }, ref) {
  const { interactionOwner } = useMenu();
  const popup = useRef<HTMLDivElement | null>(null);
  useImperativeHandle<HTMLDivElement | null, HTMLDivElement | null>(
    ref,
    () => popup.current,
  );
  const glide = useGlide(".caps-dropdown-item[data-highlighted]");
  const attach = useCallback(
    (node: HTMLDivElement | null) => {
      popup.current = node;
      glide(node);
    },
    [glide],
  );
  return (
    <BaseMenu.Popup
      {...props}
      className={(state) =>
        cn(
          "caps-dropdown-popup min-w-40 rounded-box border border-base-300 bg-base-100 p-xs shadow-lg outline-none",
          resolveClassName(className, state),
        )
      }
      finalFocus={interactionOwner === "host" ? false : (finalFocus ?? true)}
      ref={attach}
    />
  );
});

/** Props accepted by DropdownMenuContent. */
export type DropdownMenuContentProps = BaseMenu.Popup.Props &
  Pick<BaseMenu.Portal.Props, "container" | "keepMounted"> &
  Pick<
    BaseMenu.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset"
  >;
/** The positioned content region for a DropdownMenu. */
export const DropdownMenuContent = forwardRef<
  HTMLDivElement,
  DropdownMenuContentProps
>(function DropdownMenuContent(
  {
    align = "end",
    alignOffset,
    children,
    container,
    keepMounted,
    side = "bottom",
    sideOffset = 4,
    ...props
  },
  ref,
) {
  return (
    <DropdownMenuPortal container={container} keepMounted={keepMounted}>
      <DropdownMenuPositioner
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <DropdownMenuPopup {...props} ref={ref}>
          {children}
        </DropdownMenuPopup>
      </DropdownMenuPositioner>
    </DropdownMenuPortal>
  );
});

const itemClasses =
  "caps-dropdown-item flex w-full items-center gap-sm rounded-field px-md py-sm text-left text-sm outline-none transition-colors hover:bg-base-200 focus-visible:bg-base-200 aria-[current=page]:bg-base-200 aria-[current=page]:font-semibold disabled:cursor-not-allowed disabled:text-base-content/40 data-disabled:cursor-not-allowed data-disabled:text-base-content/40";
/** Props accepted by DropdownMenuItem. */
export type DropdownMenuItemProps = Omit<BaseMenu.Item.Props, "onSelect"> & {
  /** Called when this item is selected. */
  onSelect?: (event: React.SyntheticEvent<HTMLDivElement>) => void;
  variant?: "default" | "destructive";
};
/** An actionable item in a DropdownMenu. */
export const DropdownMenuItem = forwardRef<HTMLElement, DropdownMenuItemProps>(
  function DropdownMenuItem(
    { className, onClick, onSelect, variant = "default", ...props },
    ref,
  ) {
    return (
      <BaseMenu.Item
        {...props}
        className={(state) =>
          cn(
            itemClasses,
            variant === "destructive" &&
              "text-error hover:bg-error hover:text-error-content focus-visible:bg-error focus-visible:text-error-content",
            resolveClassName(className, state),
          )
        }
        onClick={(event) => {
          onClick?.(event);
          if (!event.defaultPrevented) onSelect?.(event);
        }}
        ref={ref}
      />
    );
  },
);

/** Props accepted by DropdownMenuCheckboxItem. */
export type DropdownMenuCheckboxItemProps = Omit<
  BaseMenu.CheckboxItem.Props,
  "onSelect"
> &
  Pick<DropdownMenuItemProps, "onSelect">;
/** A checkable item in a DropdownMenu. */
export const DropdownMenuCheckboxItem = forwardRef<
  HTMLElement,
  DropdownMenuCheckboxItemProps
>(function DropdownMenuCheckboxItem(
  { className, onClick, onSelect, ...props },
  ref,
) {
  return (
    <BaseMenu.CheckboxItem
      {...props}
      className={(state) => cn(itemClasses, resolveClassName(className, state))}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) onSelect?.(event);
      }}
      ref={ref}
    />
  );
});

/** A visual separator in a DropdownMenu. */
export const DropdownMenuSeparator = forwardRef<
  HTMLDivElement,
  BaseMenu.Separator.Props
>(function DropdownMenuSeparator({ className, ...props }, ref) {
  return (
    <BaseMenu.Separator
      {...props}
      className={(state) =>
        cn("my-xs h-px bg-base-300", resolveClassName(className, state))
      }
      ref={ref}
    />
  );
});

/** A named set of related items; pair it with a DropdownMenuLabel. */
export const DropdownMenuGroup = BaseMenu.Group;

/** The visible name of a DropdownMenuGroup, announced with its items. */
export const DropdownMenuLabel = forwardRef<
  HTMLDivElement,
  BaseMenu.GroupLabel.Props
>(function DropdownMenuLabel({ className, ...props }, ref) {
  return (
    <BaseMenu.GroupLabel
      {...props}
      className={(state) =>
        cn(
          "px-md pb-xs pt-sm text-xs font-semibold text-base-content/60",
          resolveClassName(className, state),
        )
      }
      ref={ref}
    />
  );
});

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}

import { useCallback, useRef, type RefCallback } from "react";

import { canAnimate, motionEasing, readMotion } from "./motion.js";

type Box = Readonly<{ x: number; y: number; width: number; height: number }>;

/**
 * The attribute a row carries while the glide stands in for its highlight:
 * empty while the stand-in travels, `measure` while its resting colour is read.
 */
const glideStandInAttribute = "data-glide-stand-in";

function boxIn(host: HTMLElement, element: Element): Box {
  const outer = host.getBoundingClientRect();
  const inner = element.getBoundingClientRect();
  // Host-relative and scroll-aware, so a scrolled list glides true.
  return {
    x: inner.left - outer.left + host.scrollLeft - host.clientLeft,
    y: inner.top - outer.top + host.scrollTop - host.clientTop,
    width: inner.width,
    height: inner.height,
  };
}

function place(box: Box) {
  return {
    transform: `translate(${String(box.x)}px, ${String(box.y)}px)`,
    width: `${String(box.width)}px`,
    height: `${String(box.height)}px`,
  };
}

/**
 * One highlight that glides between a list's rows instead of blinking from
 * row to row. `lit` selects the highlighted row (keyboard or pointer). While
 * the highlight moves, a single stand-in carrying that row's own resting
 * background and radius travels from the previous row and the rows' own
 * highlights are held back, so at rest every row looks exactly as it always
 * has. Within one open list the glide remembers its last row, so leaving and
 * re-entering glides from where it was. Timing and easing are the theme's;
 * reduced motion moves the highlight at once.
 */
export function useGlide(lit: string): RefCallback<HTMLElement> {
  const detach = useRef<(() => void) | null>(null);
  // A callback ref, so a list that mounts later (a popover's) still glides.
  return useCallback(
    (element: HTMLElement | null) => {
      detach.current?.();
      detach.current = element ? attachGlide(element, lit) : null;
    },
    [lit],
  );
}

function attachGlide(element: HTMLElement, lit: string): () => void {
  if (!canAnimate(element)) return () => undefined;
  const document = element.ownerDocument;
  let current: Element | null = element.querySelector(lit);
  let last: Box | null = current ? boxIn(element, current) : null;
  let ghost: HTMLSpanElement | null = null;
  let flight: Animation | null = null;
  const standIns = new Set<Element>();

  const release = () => {
    for (const row of standIns) row.removeAttribute(glideStandInAttribute);
    standIns.clear();
    if (ghost) ghost.hidden = true;
    flight = null;
  };

  const stage = () => {
    if (ghost) return ghost;
    const created = document.createElement("span");
    created.className = "caps-glide";
    created.setAttribute("aria-hidden", "true");
    element.prepend(created);
    // The stand-in paints above the list's background, below its rows.
    element.classList.add("caps-glide-host");
    if (getComputedStyle(element).position === "static")
      element.classList.add("caps-glide-anchor");
    ghost = created;
    return created;
  };

  const glide = (to: Element, away: Element | null) => {
    const motion = readMotion(element);
    const target = boxIn(element, to);
    const from = flight && ghost ? boxIn(element, ghost) : last;
    last = target;
    flight?.cancel();
    release();
    if (motion.reduced || from === null) return;
    if (Math.abs(from.y - target.y) < 1 && Math.abs(from.x - target.x) < 1)
      return;
    // Read the row's resting highlight, not a frame of its colour transition.
    to.setAttribute(glideStandInAttribute, "measure");
    const style = getComputedStyle(to);
    const background = style.backgroundColor;
    const radius = style.borderRadius;
    for (const row of [to, away]) {
      if (!row) continue;
      row.setAttribute(glideStandInAttribute, "");
      standIns.add(row);
    }
    const stand = stage();
    stand.hidden = false;
    stand.style.backgroundColor = background;
    stand.style.borderRadius = radius;
    const animation = stand.animate([place(from), place(target)], {
      duration: motion.normal,
      easing: motionEasing(motion, motion.ease),
      fill: "forwards",
    });
    flight = animation;
    animation.addEventListener("finish", () => {
      if (flight === animation) release();
    });
  };

  const update = () => {
    const next = element.querySelector(lit);
    if (next === current) return;
    const away = current;
    current = next;
    // A row that lights from nothing glides from the remembered row.
    if (next) glide(next, away);
  };

  const observer = new MutationObserver(update);
  observer.observe(element, {
    subtree: true,
    attributes: true,
    attributeFilter: [
      "data-highlighted",
      "data-active",
      "data-navigation",
      "aria-selected",
    ],
  });
  element.addEventListener("pointerover", update);
  element.addEventListener("pointerout", update);
  return () => {
    observer.disconnect();
    element.removeEventListener("pointerover", update);
    element.removeEventListener("pointerout", update);
    flight?.cancel();
    release();
    ghost?.remove();
  };
}

import {
  useLayoutEffect,
  useState,
  useSyncExternalStore,
  type RefObject,
} from "react";

/** Resolved, element-scoped motion. Times are milliseconds and distances pixels. */
export type Motion = Readonly<{
  reduced: boolean;
  squish: number;
  fast: number;
  normal: number;
  slow: number;
  springDuration: number;
  bounce: number;
  stretch: number;
  distance: number;
  stagger: number;
  blur: number;
  shake: number;
  steps: number;
  fuse: number;
  pressDepth: number;
  pressScale: number;
  ease: string;
  easeExit: string;
}>;

const defaults: Motion = Object.freeze({
  reduced: false,
  squish: 90,
  fast: 120,
  normal: 180,
  slow: 280,
  springDuration: 320,
  bounce: 0.3,
  stretch: 0.28,
  distance: 4,
  stagger: 24,
  blur: 0,
  shake: 3,
  steps: 0,
  fuse: 1,
  pressDepth: 0.5,
  pressScale: 1,
  ease: "cubic-bezier(0.2, 0, 0, 1)",
  easeExit: "cubic-bezier(0.4, 0, 1, 1)",
});

const preference = "(prefers-reduced-motion: reduce)";

/** Read at an event boundary; no root-theme lookup, so nested tokens win. */
export function readMotion(element: Element): Motion {
  const view = element.ownerDocument.defaultView;
  if (!view) return defaults;
  const style = view.getComputedStyle(element);
  const number = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    const parsed = Number.parseFloat(value);
    return Number.isFinite(parsed) ? Math.max(0, parsed) : fallback;
  };
  const time = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    return (
      number(name, fallback) *
      (value.endsWith("s") && !value.endsWith("ms") ? 1000 : 1)
    );
  };
  const browser: Partial<Pick<Window, "matchMedia">> = view;
  const reduced = browser.matchMedia?.(preference).matches ?? false;
  const duration = (name: string, fallback: number) =>
    reduced ? 120 : time(`--stipe-motion-${name}`, fallback);
  const amount = (name: string, fallback: number) =>
    reduced ? 0 : number(`--stipe-motion-${name}`, fallback);
  return {
    reduced,
    squish: duration("squish", defaults.squish),
    fast: duration("fast", defaults.fast),
    normal: duration("normal", defaults.normal),
    slow: duration("slow", defaults.slow),
    springDuration: duration("spring-duration", defaults.springDuration),
    bounce: Math.min(1, amount("bounce", defaults.bounce)),
    stretch: amount("stretch", defaults.stretch),
    distance: amount("distance", defaults.distance),
    stagger: reduced ? 0 : time("--stipe-motion-stagger", defaults.stagger),
    blur: amount("blur", defaults.blur),
    shake: amount("shake", defaults.shake),
    steps: Math.floor(amount("steps", defaults.steps)),
    fuse: number("--stipe-motion-fuse", defaults.fuse),
    pressDepth: reduced
      ? 0
      : number("--stipe-press-depth", defaults.pressDepth),
    pressScale: reduced
      ? 1
      : number("--stipe-press-scale", defaults.pressScale),
    ease: style.getPropertyValue("--stipe-motion-ease").trim() || defaults.ease,
    easeExit:
      style.getPropertyValue("--stipe-motion-ease-exit").trim() ||
      defaults.easeExit,
  };
}

/** Live motion tokens for a mounted ref, including nested theme and OS changes. */
export function useMotion(ref: RefObject<Element | null>): Motion {
  const [motion, setMotion] = useState<Motion>(() => ({
    ...defaults,
    reduced: true,
  }));
  useLayoutEffect(() => {
    const element = ref.current;
    const view = element?.ownerDocument.defaultView;
    if (!element || !view) return;
    const update = () => {
      const next = readMotion(element);
      setMotion((previous) =>
        JSON.stringify(previous) === JSON.stringify(next) ? previous : next,
      );
    };
    update();
    const observer = new view.MutationObserver(update);
    // Observe ancestors only: animation writes to descendants must not trigger reads.
    for (
      let parent: Element | null = element;
      parent;
      parent = parent.parentElement
    ) {
      observer.observe(parent, {
        attributes: true,
        attributeFilter: ["data-theme", "class", "style"],
      });
    }
    const browser: Partial<Pick<Window, "matchMedia">> = view;
    const media = browser.matchMedia?.(preference);
    media?.addEventListener("change", update);
    return () => {
      observer.disconnect();
      media?.removeEventListener("change", update);
    };
  }, [ref]);
  return motion;
}

/** Today's feel: the defaults that components' authored timings are written against. */
export const motionDefaults: Motion = defaults;

/**
 * Scale one of a component's authored durations by the theme's tempo
 * (`--stipe-motion-normal` against its 180ms default). Today's themes return
 * the authored value unchanged; reduced motion returns 0 (nothing travels).
 */
export function motionTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round((authored * motion.normal) / defaults.normal);
}

/**
 * Scale one of a component's authored spring bounces by the theme's bounce
 * (`--stipe-motion-bounce` against its 0.3 default), so a lively control stays
 * livelier than a calm one inside every theme. A 0 theme is critically damped.
 */
export function motionBounce(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  const scaled = (authored * motion.bounce) / defaults.bounce;
  return Math.min(0.9, Math.max(0, scaled));
}

/** Scale an authored spring settle time by `--stipe-motion-spring-duration`. */
export function motionSpringTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round(
    (authored * motion.springDuration) / defaults.springDuration,
  );
}

/** A CSS easing for a Web Animation, stepped when the theme asks for it. */
export function motionEasing(motion: Motion, ease: string): string {
  return motion.steps > 0 ? `steps(${String(motion.steps)}, end)` : ease;
}

/** Whether the element can run Web Animations (not in jsdom or old engines). */
export function canAnimate(element: Element): boolean {
  return "animate" in element;
}

const globalWindow: Partial<Pick<Window, "matchMedia">> = globalThis;

function prefersReducedMotion(): boolean {
  return globalWindow.matchMedia?.(preference).matches ?? false;
}

function subscribeReducedMotion(update: () => void) {
  const media = globalWindow.matchMedia?.(preference);
  media?.addEventListener("change", update);
  return () => {
    media?.removeEventListener("change", update);
  };
}

/** Server renders assume reduced motion, so hydration never starts mid-move. */
function serverReducedMotion() {
  return true;
}

/**
 * The live reduced-motion preference alone, for controls that only need to
 * know whether to move (their timing comes from `readMotion` when they do).
 */
export function useReducedMotion(): boolean {
  return useSyncExternalStore(
    subscribeReducedMotion,
    prefersReducedMotion,
    serverReducedMotion,
  );
}

import {
  createContext,
  useContext,
  useEffect,
  useRef,
  type ReactNode,
} from "react";

/** Semantic destinations; the host owns their paint order and positioning. */
export type OverlayLayer = "popover" | "dialog" | "toast" | "tooltip";
/** Host portal roots; null keeps an overlay waiting until its layer mounts. */
export type OverlayContainers = Readonly<
  Record<OverlayLayer, HTMLElement | null>
>;

const DismissContext = createContext<
  ((listener: () => void) => () => void) | undefined
>(undefined);

const Context = createContext<OverlayContainers | null>(null);

/** Supply shell portal roots without teaching Caps about the shell's layout. */
export function OverlayRoot({
  containers,
  children,
  subscribeDismiss,
}: {
  containers: OverlayContainers;
  children?: ReactNode;
  /** Subscribe to the host losing focus to a child surface or another window. */
  subscribeDismiss?: (listener: () => void) => () => void;
}) {
  return (
    <Context.Provider value={containers}>
      <DismissContext.Provider value={subscribeDismiss}>
        {children}
      </DismissContext.Provider>
    </Context.Provider>
  );
}

/** Wait for a provided root; standalone overlays use the current document body. */
export function useOverlayRoot(layer: OverlayLayer): HTMLElement | null {
  const containers = useContext(Context);
  if (containers !== null) return containers[layer];
  return Object.hasOwn(globalThis, "document") ? document.body : null;
}

/** Retire a transient overlay when its owning host requests light dismissal. */
export function useOverlayDismiss(dismiss: () => void): void {
  const subscribe = useContext(DismissContext);
  const callback = useRef(dismiss);
  callback.current = dismiss;
  useEffect(
    () =>
      subscribe?.(() => {
        callback.current();
      }),
    [subscribe],
  );
}
